    try {
        inv.add("ghost", 0);
    } catch (const std::invalid_argument&) {
        refused = true;
    }
    assert(refused);

    std::cout << "kinds " << inv.kinds() << "\n";
    std::cout << "total " << inv.total() << "\n";
    std::cout << "refused " << refused << "\n";
    return 0;
}

